import java.util.*;

class DetectSquares {
    private Map<Integer, Map<Integer, Integer>> countByX = new HashMap<>();
    private List<int[]> points = new ArrayList<>();

    public DetectSquares() {
    }

    public void add(int[] point) {
        points.add(point);
        countByX.computeIfAbsent(point[0], k -> new HashMap<>()).merge(point[1], 1, Integer::sum);
    }

    public int count(int[] point) {
        int px = point[0], py = point[1];
        int total = 0;
        for (int[] p : points) {
            int x = p[0], y = p[1];
            if (x == px || y == py || Math.abs(x - px) != Math.abs(y - py)) continue;
            int c1 = countByX.getOrDefault(px, Collections.emptyMap()).getOrDefault(y, 0);
            int c2 = countByX.getOrDefault(x, Collections.emptyMap()).getOrDefault(py, 0);
            total += c1 * c2;
        }
        return total;
    }
}
